+ import { categories, products } from './catalog.mjs'

function csvField(value) {
  const text = String(value)
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

function productToCsv(product) {
  return [
    'sku,name,price',
    [product.sku, product.name, product.price].map(csvField).join(','),
  ].join('\n') + '\n'
}

export function createApp() {
  const app = express()
  app.disable('x-powered-by')
  app.use(express.json({ limit: '50kb' }))

  app.get('/api/health', (req, res) => {
    res.json({ ok: true })
  })

  app.get('/api/products', (req, res) => {
    res.json({ products })
  })

  app.get('/api/products/:ref', (req, res) => {
    const asCsv = req.params.ref.endsWith('.csv')
    const sku = asCsv ? req.params.ref.slice(0, -'.csv'.length) : req.params.ref
    const product = products.find((p) => p.sku === sku)
    if (!product) {
      res.status(404).json({ error: 'not_found' })
    } else if (asCsv) {
      res.type('text/csv').send(productToCsv(product))
    } else {
      res.json(product)
    }
  })

  app.get('/api/categories/*path', (req, res) => {
    const path = req.params.path.join('/')
    if (!categories.includes(path)) {
      res.status(404).json({ error: 'not_found' })
      return
    }
    const matching = products.filter(
      (p) => p.category === path || p.category.startsWith(`${path}/`),
    )
    res.json({ path, products: matching })
  })

